from pwn import remote

# Ports to be tested
ports = [8041, 8042, 8043]
inputs = ["AAAAAA", "encrypt:test1234"]

results = []

for port in ports:
    try:
        conn = remote("crypto.chal.csaw.io", port)
        conn.recvline(timeout=2)

        port_result = {"port": port, "responses": []}

        for test_input in inputs:
            conn.sendline(test_input)
            response = conn.recvline(timeout=2).decode('utf-8', 'ignore').strip()
            port_result["responses"].append({"input": test_input, "output": response})

        results.append(port_result)
        conn.close()
    except Exception as e:
        results.append({"port": port, "error": str(e)})

# Save results to a file
with open("/home/ctfplayer/ctf_files/responses.txt", "w") as f:
    for result in results:
        f.write(f"Port {result['port']}\n")
        if "error" in result:
            f.write(f"  Error: {result['error']}\n")
        else:
            for response in result["responses"]:
                f.write(f"  Input: {response['input']}\n  Output: {response['output']}\n")
        f.write("\n")
